     applied on the Grand Total; the line discount is per unit) -->
{%- set charge_codes0 = frappe.get_all("Item", filters={"custom_charge_item": 1}, pluck="name") -%}
{% set ns = namespace(line_discount=0.0, gross=0.0, overall=0.0) %}
