    {% set ns.line_discount = ns.line_discount + dis * (item.qty | float or 0) %}
    {% set ns.gross = ns.gross + (item.amount | float or 0) + dis * (item.qty | float or 0) %}
    {% set ns.overall = ns.overall + (item.amount | float or 0) - (item.net_amount | float or 0) %}
