{% set overall_discount = ns.overall %}
{#- charge lines (freight / packing / insurance) print here, not in the item table -#}
{%- set charge_codes = frappe.get_all("Item", filters={"custom_charge_item": 1}, pluck="name") -%}
{%- set charges = doc.items | selectattr("item_code", "in", charge_codes) | list -%}
{% set cs = namespace(total=0.0, qty=0.0) %}
{% for c in charges %}{% set cs.total = cs.total + (c.amount | float or 0) %}{% set cs.qty = cs.qty + (c.qty | float or 0) %}{% endfor %}

<!-- SINGLE COMMON WRAPPER -->
<div style="margin-top: 2px; font-family: Arial, sans-serif; page-break-inside: avoid;">

    <!-- SECTION A: GST BREAKUP & FINANCIAL SUMMARY -->
    <table style="width:100%; border-collapse:collapse; border-spacing:0; font-size:9pt; line-height:1.1; border-top: 1.5px solid #000; padding-top: 2px;">
        <tr>
          <!-- LEFT: GST Breakup -->
