            <div style="font-weight:bold; font-size:9pt; margin-bottom: 1px;">
                Total Qty: {{ (doc.total_qty - cs.qty) | int }}{% if doc.custom_no_of_boxes__bundles %} | Boxes: {{ doc.custom_no_of_boxes__bundles }}{% endif %}
            </div>
            <div class="dacs-gst" style="width:100%; margin:0; padding:0; line-height: 0.9;">
