     <span style="font-style:italic; font-weight:bold;">Rupees {{ frappe.utils.money_in_words(doc.rounded_total or doc.grand_total) }} Only</span>

     {% set company_doc = frappe.get_doc("Company", doc.company) %}
     {% if company_doc.bank_details_for_printing %}
        <div style="border-top:1px solid #eee; margin-top:3px; padding-top:3px; font-size:8pt;">
            <strong>Bank

            {% set printed = [] %}
            {% for d in company_doc.bank_details_for_printing %}
                {% if d.print_label and d.print_value %}
                    {{ d.print_label }}: {{ d.print_value }}{% if not loop.last %} | {% endif %}
                {% endif %}
            {% endfor %}
            </strong>
        </div>
    {% endif %}
  </div>

  <!-- 5. Terms & Signature (Reduced Heights) -->
  <table style="width:100%; border:1px solid #000; border-collapse:collapse; table-layout: fixed; border-top: none;">
      <tr>
          <!-- Terms Side -->
          <td style="width:70%; font-size:7.5pt; border-right:1px solid #000; padding: 4px 6px; vertical-align: top;">
              {% if doc.remarks %}
                  <div style="margin-bottom:2px;"><strong>Remarks:</strong> {{ doc.remarks }}</div>
              {% endif %}

              {% if doc.terms %}
                  <div style="font-weight:bold; text-decoration:underline; margin-bottom:2px;">Terms & Conditions:</div>
                  <div style="line-height: 1.1; white-space: normal !important; word-wrap: break-word; text-align: left;">
                      {{ doc.terms | safe }}
                  </div>
              {% endif %}
          </td>

          <!-- Signature Side (Optimized Gap) -->
          <td style="width:30%; vertical-align:top; text-align:center; padding:8px 4px 4px 4px;">
              <div style="font-size:8.5pt; font-weight:bold; margin-bottom:42px;">
                  For {{ doc.company }}
              </div>
              <div style="display:inline-block; border-top:1px solid #000; padding-top:2px; width:90%; font-weight:bold; font-size:8.5pt;">
                  Authorised Signatory
              </div>
          </td>
      </tr>
  </table>
</div>"}]
